///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCode = async function() {
    const sbmOptions = {
        id : "sbm_dts_ElwInst",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_ElwInst=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // alert("call");

};

/**
 * @method
 * @name listSync
 * @description list Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    let urlcond = '';
    urlcond += "&ISUR_CD=" + cmb_ISUR_CD.getValue();
    urlcond += "&LIST_PROCS_STAT_CD=" + cmb_LIST_PROCS_STAT_CD.getValue();
    if (MaxTab_01.getSelectedTabIndex() === 1) {
        url += urlcond;
        // alert("vListMdCd :"+vListMdCd);
        url += "&SCREN_ID=" + "ULDSTF05905.xml";
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        const sbmOptions = {
            id : "sbm_dts_List_1",
            action : "/ElwListedReceive.do",
            ref : "",
            target : "dts_List_1=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    } else if (MaxTab_01.getSelectedTabIndex() === 2) {
        url += urlcond;
        // alert("vListMdCd :"+vListMdCd);
        url += "&SCREN_ID=" + "ULDSTF05905.xml";
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        const sbmOptions = {
            id : "sbm_dts_List_2",
            action : "/ElwListedReceive.do",
            ref : "",
            target : "dts_List_2=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    }
};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setBzProcsNo
 * @description set Bz Procs No 처리
 * @param {Object} obj 컴포넌트
 * @param {*} dtsObj dtsObj
 * @returns {void}
 * @hidden N
 */
scwin.setBzProcsNo = function(obj, dtsObj) {
    scwin.clickBzProcsNo = dtsObj.getCellData(Number(obj), "BZ_PROCS_NO");
};

/**
 * @method
 * @name openDetail
 * @description open Detail 처리
 * @param {Number} row 행 인덱스
 * @param {*} dtsObj dtsObj
 * @returns {void}
 * @hidden N
 */
scwin.openDetail = function(row, dtsObj) {
    scwin.setBzProcsNo(row, dtsObj);
    const vbzTpCd = dtsObj.getCellData(row, "LIST_BZ_TP_CD");
    $c.elw.fn_OpenDetailRecv(vbzTpCd);
};

/**
 * @method
 * @name getbzTpCd
 * @description getbz Tp Cd 처리
 * @returns {void}
 * @hidden N
 */
scwin.getbzTpCd = function() {
    if (MaxTab_01.getSelectedTabIndex() === 1) {
        vLIST_BZ_TP_CD = LIST_BZ_TP_CD_003;
    } else if (MaxTab_01.getSelectedTabIndex() === 2) {
        vLIST_BZ_TP_CD = LIST_BZ_TP_CD_005;
    }
    return vLIST_BZ_TP_CD;
};

/**
 * @method
 * @name getPopWindowNm
 * @description get Pop Window Nm 처리
 * @returns {void}
 * @hidden N
 */
scwin.getPopWindowNm = function() {
    let screenNm;
    scwin.getbzTpCd();
    if (vLIST_BZ_TP_CD === LIST_BZ_TP_CD_003) {
        screenNm = "신규상장";
    } else if (vLIST_BZ_TP_CD === LIST_BZ_TP_CD_005) {
        screenNm = "추가상장";
    }
    return screenNm;
};

/**
 * @method
 * @name openDetailListDD
 * @description open Detail List DD 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openDetailListDD = async function() {
    const options = {
        id: "ULDSTF05906",
        title: scwin.getPopWindowNm() + " 상장일지정",
        type: "browserPopup",
        width: "630px",
        height: "440px",
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("/lstproc/ULDSTF05906.gfm", options);
};

/**
 * @method
 * @name openDetailDscl
 * @description open Detail Dscl 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openDetailDscl = async function() {
    const options = {
        id: "ULDSTF05907",
        title: scwin.getPopWindowNm() + " 안내문작성",
        type: "browserPopup",
        width: "535px",
        height: "670px",
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("/lstproc/ULDSTF05907.gfm", options);
};

/**
 * @method
 * @name excelDown
 * @description 정보를 excel로 다운 받는다.
 * @returns {void}
 * @hidden N
 */
scwin.excelDown = function() {
    if (MaxTab_01.getSelectedTabIndex() === 1) {
        $c.data.downloadGridViewExcel(grd_List_1, {fileName: "신규상장처리", type: "8"});
    } else if (MaxTab_01.getSelectedTabIndex() === 2) {
        $c.data.downloadGridViewExcel(grd_List_2, {fileName: "추가상장처리", type: "8"});
    }
};
